import{at as e,it as t,n,vt as r}from"./chunks/framework.DbV_8hbX.js";var i=JSON.parse(`{"title":"SDK tag and optional integrations","description":"","frontmatter":{},"headers":[],"relativePath":"en/integration/sdk.md","filePath":"en/integration/sdk.md","lastUpdated":1794405696000}`),a={name:`en/integration/sdk.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="sdk-tag-and-optional-integrations" tabindex="-1">SDK tag and optional integrations <a class="header-anchor" href="#sdk-tag-and-optional-integrations" aria-label="Permalink to “SDK tag and optional integrations”">​</a></h1><p>Place one shared tag on your site. You aren&#39;t required to register a product ID or description for each page. You need permission over the site settings, permission to edit the site where you implement it, and a design for user consent.</p><h2 id="the-shared-tag" tabindex="-1">The shared tag <a class="header-anchor" href="#the-shared-tag" aria-label="Permalink to “The shared tag”">​</a></h2><div class="language-html" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">script</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  defer</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://YOUR-API-HOST/sdk.js&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  data-api</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://YOUR-API-HOST&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  data-site</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;YOUR-SITE-ID&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p><code>defer</code> downloads the SDK without blocking HTML parsing and runs it after parsing finishes. An inline script right after the tag doesn&#39;t wait for the SDK to finish running, so call the consent API after the SDK has finished loading.</p><p>Make <code>data-site</code> match the site ID in the admin console. Specify an HTTPS origin for the API. HTTP is allowed only for localhost during local development.</p><p>&quot;Verification (「動作確認」)&quot; in the admin console also shows a tag example for the selected site. Don&#39;t put the Jev API key or an admin token in the tag.</p><h2 id="start-after-consent" tabindex="-1">Start after consent <a class="header-anchor" href="#start-after-consent" aria-label="Permalink to “Start after consent”">​</a></h2><p>Call this when you&#39;ve obtained consent, for example from a CMP, after the SDK has finished loading.</p><div class="language-js" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.JevPersonalization.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">consent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Before consent, observation and normal sending don&#39;t start. To withdraw consent:</p><div class="language-js" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.JevPersonalization.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">consent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>On withdrawal, the target history in the browser that this SDK uses is also erased.</p><p>Only if appropriate consent has already been obtained, you can instead add <code>data-consent=&quot;granted&quot;</code> to the tag. Don&#39;t treat consent as given simply because the tag was loaded.</p><p>Calling the API before loading fails, so adjust the order in which your CMP and the tag run. Adapt it to your site&#39;s tag manager or SPA setup.</p><h2 id="admin-console-settings" tabindex="-1">Admin console settings <a class="header-anchor" href="#admin-console-settings" aria-label="Permalink to “Admin console settings”">​</a></h2><ul><li>Register your real site&#39;s origin under origins.</li><li>Set the paths to collect and the paths to exclude.</li><li>Check the page information and enable metadata sending.</li><li>Create a campaign, set the display target paths and start delivery.</li></ul><p>If any of these is disabled or doesn&#39;t match, nothing is displayed even if the tag is present.</p><h2 id="optional-events-and-states" tabindex="-1">Optional events and states <a class="header-anchor" href="#optional-events-and-states" aria-label="Permalink to “Optional events and states”">​</a></h2><p>Only names registered in the admin console are accepted. Use them for information you can&#39;t tell from page views alone, such as applications, bookings and carts.</p><div class="language-js" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// If you registered guide_download in actionNames</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.JevPersonalization.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">track</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;guide_download&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// If you registered registered in factNames</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.JevPersonalization.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setFact</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;registered&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// When the registration is complete</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.JevPersonalization.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setFact</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;registered&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>An event&#39;s value can be omitted, or be a boolean or a finite number. A state is a boolean or a finite number. These APIs are not for passing names, email addresses or form input.</p><p>If a campaign&#39;s excluded fact is <code>registered</code>, an unknown value is not treated as &quot;not registered&quot;. Pass false while incomplete and true when complete.</p><h2 id="when-it-communicates" tabindex="-1">When it communicates <a class="header-anchor" href="#when-it-communicates" aria-label="Permalink to “When it communicates”">​</a></h2><p>After consent and loading of the site settings, it requests the initial display decision exactly once for each page to collect. It doesn&#39;t wait for the current page&#39;s minimum viewing time. In a tab opened in the background, it requests once the tab becomes visible.</p><table tabindex="0"><thead><tr><th>Trigger</th><th>Communication with the decision API</th><th>Update in the browser</th></tr></thead><tbody><tr><td>First display, normal page navigation</td><td>Once</td><td>Reads the current page and the entry page</td></tr><tr><td>SPA path change</td><td>Once for the new page</td><td>Reads the settings, then the current page after 200 ms</td></tr><tr><td>Reaching the minimum viewing time</td><td>None</td><td>Saves to the valid view history</td></tr><tr><td><code>track()</code>, <code>setFact()</code></td><td>None</td><td>Carried to the next page&#39;s initial decision</td></tr><tr><td>Only a metadata or query change</td><td>None</td><td>Updates the current page&#39;s information</td></tr><tr><td>Time passing, re-running <code>decide()</code></td><td>None</td><td>Continues measuring and saving</td></tr></tbody></table><p>Even if communication fails or the settings version is outdated, the same page is not judged again. A new initial decision happens on the next navigation or reload. The valid view history is used in the next page&#39;s decision. Even when a request is sent to the API, nothing is sent to Jev unless the delivery conditions and the required history are met. A campaign decided only by confirmed URL conditions doesn&#39;t use Jev either.</p><h2 id="urls-and-tracking-codes" tabindex="-1">URLs and tracking codes <a class="header-anchor" href="#urls-and-tracking-codes" aria-label="Permalink to “URLs and tracking codes”">​</a></h2><p>The current page, the entry page and past valid views keep the URL including its GET parameters. Under &quot;Site settings → Page information fetching → GET parameter keys not to collect&quot;, specify one per line the keys you want to remove from saving and sending. If empty, all GET parameters are kept. Everything after <code>#</code>, and any username or password in the URL, is always removed.</p><p>For example, if you exclude <code>email</code>, <code>?cid=mail_runner&amp;email=a%40example.com</code> becomes <code>?cid=mail_runner</code>. Excluded keys are matched exactly and case-sensitively. If search terms or personal information appear in URLs, exclude the corresponding keys or pages.</p><h2 id="spas-csp-and-checking" tabindex="-1">SPAs, CSP and checking <a class="header-anchor" href="#spas-csp-and-checking" aria-label="Permalink to “SPAs, CSP and checking”">​</a></h2><p>SPA navigation and metadata changes are also observed, but check them against your site&#39;s own routing, JSON-LD and CMP.</p><p>In your CSP, allow the origins for the SDK script, connections to the API, displayed images and any custom JavaScript modules you need. Set them narrowly to match your site&#39;s existing policy.</p><p>For the private Preview protected by Access, passing the authentication cookie is explicitly enabled only for same-origin check pages. You don&#39;t need this check option when adding it to a normal site, and it doesn&#39;t send the authentication cookie to a different origin.</p>`,34)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};